def findBlackPixel(picture, target):
    m, n = len(picture), len(picture[0])
    # Convert each row to a string to compare rows easily
    patterns = [''.join(row) for row in picture]
    row_counts = [p.count('B') for p in patterns]

    # Count black pixels in each column
    col_counts = [0] * n
    for p in patterns:
        for j, ch in enumerate(p):
            if ch == 'B':
                col_counts[j] += 1

    res = 0
    for j in range(n):
        if col_counts[j] != target:
            continue
        # Distinct rows among those with a black pixel in column j
        rows_with_b = {patterns[i] for i in range(m) if patterns[i][j] == 'B'}
        if len(rows_with_b) == 1:
            p = next(iter(rows_with_b))
            if p.count('B') == target:
                res += target
    return res
